package com.example.rokidkeyboardbridge;
public final class CharacterVisualRefinementTest {
 static int n;static void ok(boolean b,String m){n++;if(!b)throw new AssertionError(m);}
 public static void main(String[] args){
  CharacterGestureVariation v=new CharacterGestureVariation();ok(v.choose(0,1000,false)==0,"first semantic wave");ok(v.choose(0,2000,false)==-1,"consecutive conversational wave suppressed");ok(v.choose(0,2500,true)==0,"explicit repeated request preserved");ok(v.choose(1,3000,false)==1,"new semantic motion retained");ok(v.choose(1,22000,false)==1,"cooldown expires");v.clear();ok(v.choose(1,2000,false)==1,"session cleared");
  ok(CharacterContactPoint.context("頬に触れる")==CharacterContactPoint.CHEEK,"cheek intent");ok(CharacterContactPoint.context("手を取る")==CharacterContactPoint.HAND,"hand intent");ok(CharacterContactPoint.context("肩に触れる")==CharacterContactPoint.SHOULDER,"shoulder intent");
  for(boolean portrait:new boolean[]{false,true})for(int zone=0;zone<3;zone++){float y=CharacterContactPoint.vertical(zone,portrait);CharacterContactPoint.note(.2f,y,portrait,1000);ok(CharacterContactPoint.resolve("",1100)==zone,"point wins over generic context");ok(CharacterContactPoint.horizontal(1100)==.2f,"look toward touched side");ok(CharacterContactPoint.resolve("手を取る",1400)==CharacterContactPoint.HAND,"stale point ignored");}
  CharacterContactPoint.note(Float.NaN,.2f,false,2000);ok(CharacterContactPoint.horizontal(2500)==.5f,"invalid/old point ignored");
  for(int clip:new int[]{0,2,4,6,22,24})for(int frame=0;frame<4;frame++){float head=StandingGestureAtlas.headCenter(clip,frame,1536);int[] b=StandingGestureAtlas.bounds(clip,frame,1536,2048);ok(head>0&&head<b[2]-b[0],"annotated head inside crop");}
  float[] mesh=new float[17*33*2];for(int row=0;row<=32;row++)for(int col=0;col<=16;col++){int i=(row*17+col)*2;mesh[i]=240*col/16f+4;mesh[i+1]=600*row/32f+3;}StandingGestureAtlas.protectHead(mesh,16,32,240,600,0,600);
  for(int row=0;row<=32;row++)for(int col=0;col<=16;col++){int i=(row*17+col)*2;ok(Float.isFinite(mesh[i])&&Float.isFinite(mesh[i+1]),"finite anatomy mesh");if(row/32f<=.19f)ok(mesh[i]==240*col/16f&&mesh[i+1]==600*row/32f,"head rigid through gestures");if(row/32f>=.27f)ok(mesh[i]==240*col/16f+4,"lower animation preserved");}
  CharacterContactPoint.note(.5f,.32f,false,true,3000);ok(CharacterContactPoint.resolve("",3100)==CharacterContactPoint.CHEEK,"seated face is lower in viewport");CharacterContactPoint.note(.5f,.66f,false,true,4000);ok(CharacterContactPoint.resolve("",4100)==CharacterContactPoint.HAND,"seated lap/hand area");CharacterContactPoint.note(.25f,.40f,false,false,5000);ok(CharacterContactPoint.resolve("",5100)==CharacterContactPoint.HAND,"extended palm beside torso");
  CharacterGestureLife life=new CharacterGestureLife();life.performance.user("手帳に書いて");life.answer("書き留めます。",FullBodyPoseCatalog.Kind.NEUTRAL,1000);ok(life.bodyClip(1100,false)==24,"explicit notes rendered");life.answer("書き留めます。",FullBodyPoseCatalog.Kind.NEUTRAL,2000);ok(life.bodyClip(2100,false)==24,"explicit notes repeat bypasses cooldown");life.clear();life.event(CharacterGestureLife.EXPLAIN,3000,true);life.event(CharacterGestureLife.EXPLAIN,4000,true);ok(life.bodyClip(4100,false)==0,"explicit preview repeat works");
  System.out.println("PASS "+n+" character identity anchors, regional touch and repetition checks");
 }
}
